def middle(s):
    n = len(s)
    if n == 0:
        return ''
    mid = n // 2
    if n % 2 == 1:
        return s[mid]
    return s[mid-1:mid+1]

print(middle('a'))
print(middle('ab'))

def strip_ends(s):
    if len(s) <= 2:
        return ''
    return s[1:-1]

print(strip_ends('python'))
print(strip_ends('a'))

def reverse_string(text):
    reversed_text = ''
    for i in range(len(text) - 1, -1, -1):
        reversed_text += text[i]
    return reversed_text

print(reverse_string('hello'))

def dynamic_slice(text, start, end):
    if not (0 <= start <= end <= len(text)):
        raise ValueError('Invalid slice indices: ensure 0 <= start <= end <= len(text)')
    return text[start:end]

print(dynamic_slice('abcdef', 1, 4))
print(dynamic_slice('abcdef', 2, 1))
